/* Seed snapshots plus recorded games reconstruct every series after reload. */
function playoffBracketSize(rules=leagueRules(),teams=state.teams){return rules.playoffFormat==='top4'?4:rules.playoffFormat==='eight'?8:rules.playoffFormat==='sixteen'?16:teams.length>=16?16:4}
function validatePlayoffRules(rules,teams){const size=playoffBracketSize(rules,teams),byes=rules.firstRoundByes,entrants=size-byes;if(byes>size/2)throw Error('First-round byes cannot exceed half of the bracket slots.');if(entrants>teams.length)throw Error('This playoff bracket needs '+entrants+' teams. Reduce the bracket or add first-round byes.');const conferences=[...new Set(teams.map(t=>t.conference))];if(rules.splitPlayoffs&&conferences.length===2&&conferences.every(c=>teams.filter(t=>t.conference===c).length>=Math.ceil(entrants/2))&&byes%2)throw Error('Conference-split brackets need an even number of first-round byes.');}
function playoffRoundGames(c,stage){return c.roundGames?.[stage]||c.bestOf}
function playoffSeriesFormat(c){const lengths=playoffStages(c).map(stage=>playoffRoundGames(c,stage));return lengths.every(n=>n===lengths[0])?(lengths[0]===1?'Single elimination':'Best of '+lengths[0]):'Custom series by round'}
function playoffRoundSummary(c){return playoffStages(c).map(stage=>playoffStageLabel(stage,c)+': Best of '+playoffRoundGames(c,stage)).join(' · ')}
function createPlayoffConfig(){const teams=rank().filter(t=>!expansionPendingSeason(t)),legacy=playoffGames().length>0&&!state.playoffConfig,rules=legacy?{...leagueRules(),playoffFormat:playoffGames().some(g=>g.stage==='First round')?'sixteen':'top4',firstRoundByes:0,seriesGames:1,splitPlayoffs:playoffGames().some(g=>g.stage==='First round')}:leagueRules(),size=playoffBracketSize(rules,teams),byes=rules.firstRoundByes,entrants=size-byes,conferences=[...new Set(teams.map(t=>t.conference))],split=rules.splitPlayoffs&&byes%2===0&&conferences.length===2&&conferences.every(c=>teams.filter(t=>t.conference===c).length>=entrants/2);return {year:state.year,size,byes,bestOf:rules.seriesGames,roundGames:Object.fromEntries(playoffStages({size}).map(stage=>[stage,legacy?1:rules[{'First round':'seriesFirstGames','Conference semifinal':'seriesQuarterGames','Conference final':'seriesSemiGames','Semifinal':'seriesSemiGames','Championship':'seriesFinalGames'}[stage]]||rules.seriesGames])),split,sides:split?conferences.map(name=>({name,teams:rankStandings(teams.filter(t=>t.conference===name)).slice(0,entrants/2).map(t=>t.id)})):[{name:'League',teams:teams.slice(0,entrants).map(t=>t.id)}]}}
function playoffConfig(){return state.playoffConfig||createPlayoffConfig()}
function readPlayoffConfig(raw,career){const fail=()=>{throw Error('Invalid saved playoff bracket.')};if(!raw||raw.year!==career.year||![4,8,16].includes(raw.size)||![1,3,5,7].includes(raw.bestOf)||!Number.isInteger(raw.byes)||raw.byes<0||raw.byes>raw.size/2||typeof raw.split!=='boolean'||raw.split&&raw.byes%2||!Array.isArray(raw.sides)||raw.sides.length!==(raw.split?2:1))fail();if(raw.roundGames!==undefined&&(!raw.roundGames||typeof raw.roundGames!=='object'||Array.isArray(raw.roundGames)||Object.keys(raw.roundGames).length!==playoffStages(raw).length||playoffStages(raw).some(stage=>![1,3,5,7].includes(raw.roundGames[stage]))))fail();const ids=[];for(const side of raw.sides){if(!side||typeof side.name!=='string'||side.name.length>35||!Array.isArray(side.teams)||side.teams.length!==(raw.size-raw.byes)/raw.sides.length||side.teams.some(id=>!Number.isInteger(id)||!career.teams[id]||ids.includes(id)))fail();ids.push(...side.teams)}if(new Set(ids).size!==ids.length)fail();return {year:raw.year,size:raw.size,byes:raw.byes,bestOf:raw.bestOf,roundGames:Object.fromEntries(playoffStages(raw).map(stage=>[stage,raw.roundGames?.[stage]||raw.bestOf])),split:raw.split,sides:raw.sides.map(s=>({name:s.name,teams:[...s.teams]}))}}
playoffGames=function(){return state.history.filter(g=>g.stage!=='Regular season')};
playoffField=function(){return playoffConfig().sides.flatMap(s=>s.teams.map(id=>state.teams[id]))};
usesConferencePlayoffs=function(){return playoffConfig().split};
conferencePlayoffGroups=function(){const c=playoffConfig();return c.split?c.sides.map(s=>({name:s.name,teams:s.teams.map(id=>state.teams[id])})):null};
function playoffSeedOrder(size){if(size===2)return [1,2];if(size===4)return [1,4,2,3];if(size===8)return [1,8,4,5,3,6,2,7];let seeds=[1,2];while(seeds.length<size){const n=seeds.length*2+1;seeds=seeds.flatMap(s=>[s,n-s])}return seeds}
function playoffOpeningPairs(c=playoffConfig()){return c.sides.flatMap(s=>{const order=playoffSeedOrder(c.size/c.sides.length).map(seed=>s.teams[seed-1]??null),pairs=[];for(let i=0;i<order.length;i+=2)pairs.push(order.slice(i,i+2));return pairs})}
firstRoundPairs=function(){return playoffOpeningPairs()};
function playoffStages(c=playoffConfig()){return c.size===16?['First round','Conference semifinal','Conference final','Championship']:c.size===8?['First round','Semifinal','Championship']:['Semifinal','Championship']}
function playoffStageLabel(stage,c=playoffConfig()){return stage==='Conference semifinal'&&!c.split?'Quarterfinal':stage==='Conference final'&&!c.split?'Semifinal':stage==='Semifinal'&&c.split?'Conference final':stage}
function playoffSeriesSlots(){const c=playoffConfig(),ranking=rank().map(t=>t.id),slots=[];let pairs=playoffOpeningPairs(c);for(const [round,stage] of playoffStages(c).entries()){
 const bestOf=playoffRoundGames(c,stage);const current=pairs.map((initial,index)=>{const pair=initial.filter(id=>id!==null&&id!==undefined).sort((a,b)=>(c.sides.find(s=>s.teams.includes(a)&&s.teams.includes(b))?c.sides.find(s=>s.teams.includes(a)).teams.indexOf(a)-c.sides.find(s=>s.teams.includes(b)).teams.indexOf(b):ranking.indexOf(a)-ranking.indexOf(b))),bye=round===0&&pair.length===1,games=pair.length===2?playoffGames().filter(g=>g.stage===stage&&pair.includes(g.a)&&pair.includes(g.b)).slice().reverse():[],wins=pair.map(id=>games.filter(g=>g.winner===id).length),winner=bye?pair[0]:pair.find((id,i)=>wins[i]>=Math.ceil(bestOf/2)),complete=winner!==undefined,gameNumber=games.length+1,homeFirst=bestOf===7?[true,true,false,false,true,false,true][games.length]:bestOf===5?[true,true,false,false,true][games.length]:bestOf===3?[true,false,true][games.length]:true;return {stage,bestOf,round,index,pair,bye,games,wins,winner,complete,result:complete&&!bye?games.at(-1):null,nextPair:homeFirst?pair:[...pair].reverse(),gameNumber}});
 slots.push(...current);if(current.some(s=>!s.complete))break;const winners=current.map(s=>s.winner);pairs=[];for(let i=0;i<winners.length;i+=2)pairs.push(winners.slice(i,i+2));}return slots}
playoffScheduleSlots=function(){return playoffSeriesSlots()};
function playoffSeriesCard(s,actions=true){const c=playoffConfig(),heading=playoffStageLabel(s.stage,c),title=s.bye?'First-round bye':s.complete?'Series final':`Game ${s.gameNumber} · Best of ${s.bestOf}`;return `<section class="po-match"><h3>${escapeHTML(heading)} · ${title}</h3>${s.pair.map((id,i)=>{const t=state.teams[id],seed=c.sides.find(side=>side.teams.includes(id)).teams.indexOf(id)+1;return `<div class="po-team ${s.winner===id?'po-winner':''}"><small>${seed}</small>${secondaryTeamLogo(t)}<span>${escapeHTML(t.city+' '+t.name)}${!s.complete?`<small>Next game · ${s.nextPair[0]===id?'Home':'Away'}</small>`:''}</span><b>${s.bye?'BYE':s.wins[i]}</b></div>`}).join('')}${s.bye?'<p class="muted">Advances automatically. No game or stats recorded.</p>':`<p class="muted">${s.complete?escapeHTML(state.teams[s.winner].name)+' advance.':'First to '+Math.ceil(s.bestOf/2)+' wins.'}</p>`}${s.games.map((g,i)=>`<button onclick="showResult(${state.history.indexOf(g)})">Game ${i+1}: ${g.sa}–${g.sb}</button>`).join(' ')}${actions&&!s.bye?`<button onclick="viewPlayoffMatchup(${s.pair.join(',')})">View matchup</button>`:''}${actions&&!s.complete&&state.day===seasonLength()&&state.champion===null?`<div class="schedule-watch-actions"><button onclick="simulatePlayoffGame(${s.nextPair.join(',')})">Simulate game</button><button class="primary" onclick="simulatePlayoffGame(${s.nextPair.join(',')},true)">Watch live</button></div>`:''}</section>`}
playoffBracket=function(){const c=playoffConfig(),slots=playoffSeriesSlots();return `<section class="po-panel"><h2>PLAYOFF BRACKET · ${state.year}</h2><p>${escapeHTML(playoffRoundSummary(c))}</p><p>${c.size-c.byes} teams · ${playoffSeriesFormat(c)} · ${c.byes} first-round byes · ${c.split?'Separate conference sides':'League-wide seeding'}</p><div class="conference-brackets">${c.sides.map((side,sideIndex)=>`<section><h3>${escapeHTML(side.name)}</h3>${playoffStages(c).filter(stage=>!c.split||stage!=='Championship').map(stage=>{const games=slots.filter(s=>s.stage===stage&&(!c.split||s.pair.some(id=>side.teams.includes(id))));return games.length?`<div class="conference-round">${games.map(s=>playoffSeriesCard(s)).join('')}</div>`:''}).join('')}</section>`).join('')}</div>${c.split?slots.filter(s=>s.stage==='Championship').map(s=>playoffSeriesCard(s)).join(''):''}<p class="po-muted">The next round appears when all series in the current round are complete.</p></section>`};
function playoffSeriesWinChance(a,b,bestOf){const p=1/(1+Math.exp((strength(state.teams[b])-strength(state.teams[a]))/8)),need=Math.ceil(bestOf/2);let sum=0;for(let losses=0;losses<need;losses++){let combinations=1;for(let k=1;k<=losses;k++)combinations=combinations*(need+k-1)/k;sum+=combinations*p**need*(1-p)**losses}return sum}
playoffOdds=function(){const c=playoffConfig();if(state.champion!==null)return playoffField().map(t=>({t,chance:t.id===state.champion?1:0}));let nodes=c.sides.flatMap(s=>playoffSeedOrder(c.size/c.sides.length).map(seed=>s.teams[seed-1]===undefined?[]:[{id:s.teams[seed-1],p:1}]));let round=0;while(nodes.length>1){const bestOf=playoffRoundGames(c,playoffStages(c)[round++]),next=[];for(let i=0;i<nodes.length;i+=2){const a=nodes[i],b=nodes[i+1];next.push(!a.length?b:!b.length?a:[...a.map(x=>({id:x.id,p:x.p*b.reduce((sum,y)=>sum+y.p*playoffSeriesWinChance(x.id,y.id,bestOf),0)})),...b.map(x=>({id:x.id,p:x.p*a.reduce((sum,y)=>sum+y.p*playoffSeriesWinChance(x.id,y.id,bestOf),0)}))])}nodes=next}return nodes[0].map(x=>({t:state.teams[x.id],chance:x.p})).sort((a,b)=>b.chance-a.chance)};
playoffsView=function(){const c=playoffConfig(),remaining=seasonLength()-state.day,champion=state.champion===null?null:state.teams[state.champion],content=playoffTab==='teams'?playoffStats():playoffTab==='players'?playoffStats(true):playoffTab==='champions'?playoffChampions():playoffTab==='games'?`<section class="po-panel"><h2>PLAYOFF GAMES</h2>${playoffGames().map(g=>playoffMatch([g.a,g.b],playoffStageLabel(g.stage).toUpperCase(),g)).join('')||'<p>Results appear after the first playoff game.</p>'}</section>`:playoffBracket();return `<div class="playoffs-page">${pageHeaderFor('Playoffs')}<nav class="po-tabs" aria-label="Playoff views">${[['bracket','Playoff bracket'],['games','Games'],['teams','Team stats'],['players','Player stats'],['champions','Past champions']].map(([id,label])=>`<button aria-pressed="${playoffTab===id}" class="${playoffTab===id?'selected':''}" onclick="switchPlayoffTab('${id}')">${label}</button>`).join('')}</nav><section class="po-summary"><div><small>POSTSEASON</small><strong>${remaining>0?'In '+remaining+' days':champion?'Complete':'In progress'}</strong><span>${champion?escapeHTML(champion.name)+' · Champions':scheduleDateLabel(seasonLength(),true)+' · Regular season ends'}</span></div><div><small>TEAMS</small><strong>${c.size-c.byes}</strong><span>${c.split?(c.size-c.byes)/2+' per conference':'League-wide seeds'}</span></div><div><small>SERIES</small><strong>${playoffSeriesFormat(c)}</strong><span>${c.byes} first-round byes</span></div></section><div class="po-actions">${simulateRoundButton()}${remaining===0?`<button class="primary" onclick="${champion?'newSeason()':'playoffs()'}">${champion?'Continue offseason':'Simulate remaining playoffs'}</button>`:'<p>Complete the regular season to lock the seeds.</p>'}</div>${content}<section class="po-panel"><h2>${champion?'FINAL OUTCOME':'TITLE CHANCES'}</h2>${playoffOdds().map(({t,chance})=>`<div class="po-odds"><span>${secondaryTeamLogo(t)} ${escapeHTML(t.city+' '+t.name)}</span><b>${(chance*100).toFixed(1)}%</b></div>`).join('')}<p class="po-muted">Rating-based estimates for this bracket and series length.</p></section></div>`};
let playoffBatchToken=null;
function simulateRoundButton(){return state.day===seasonLength()&&state.champion===null?'<button onclick="simulatePlayoffRound()" '+(playoffBatchToken?'disabled':'')+'>Simulate round</button>':''}
function playoffSimulationProgress(slot,done,total,summary,unit='Playoff series completed'){simulationProgress(done,total,state.day+1,0,0,{status:slot?playoffStageLabel(slot.stage)+' · Game '+slot.gameNumber+' · '+slot.nextPair.map(id=>state.teams[id].city+' '+state.teams[id].name).join(' vs. '):'Playoff simulation complete',summary,unit,stop:'Stop after this game',stopping:'Finishing this game…'});}
function closePlayoffSimulationProgress(){if(!simulationHeadless()){const dialog=document.getElementById('simulation-progress');if(dialog?.open)dialog.close();}}
simulatePlayoffGame=async function(a,b,watch=false,batchToken=null){if((playoffBatchToken&&batchToken!==playoffBatchToken)||playoffActionBusy||!gmCanAdvance()||state.day!==seasonLength()||state.champion!==null)return;const slot=playoffSeriesSlots().find(s=>!s.complete&&s.nextPair[0]===a&&s.nextPair[1]===b);if(!slot)return;playoffActionBusy=true;const before=snapshotState();let game;const ownProgress=!batchToken;try{if(ownProgress){simulationStopRequested=false;playoffSimulationProgress(slot,0,1,'0 / 1 games completed','Games completed');await simulationYield();if(simulationStopRequested)return;}state.playoffConfig??=createPlayoffConfig();ownerTrack();finalizeRegularAwards();watchCapture={day:state.day+1,a,b};try{game=play(a,b,slot.stage)}finally{watchCapture=null}const final=playoffSeriesSlots().find(s=>s.stage==='Championship'&&s.complete);if(final){state.champion=final.winner;if(final.winner===controlledTeamId())state.titles++;ownerFinalize();say(state.teams[final.winner].city+' win the '+state.year+' championship!')}if(await save()===false){state=before;render();return}render();if(ownProgress)closePlayoffSimulationProgress();if(watch&&!simulationHeadless()){clearTimeout(liveWatchTimer);liveWatch={result:game,index:0,paused:false,speed:leagueRules().playbackSpeed};const dialog=watchDialog();renderWatchGame();if(!dialog.open)dialog.showModal();scheduleWatchTick()}return game}catch(e){state=before;simulationFailure(e);toast(e.message);render()}finally{playoffActionBusy=false;if(ownProgress)closePlayoffSimulationProgress()}};
async function simulatePlayoffBatch(roundOnly=false){
 if(playoffActionBusy||playoffBatchToken||!gmCanAdvance()||state.day!==seasonLength()||state.champion!==null)return;
 const round=playoffSeriesSlots().find(s=>!s.complete)?.round;if(round===undefined)return;
 const token=Symbol('playoff batch');playoffBatchToken=token;simulationStopRequested=false;
 const config=playoffConfig(),total=roundOnly?config.size/2**(round+1)-(round===0?config.byes:0):config.size-1-config.byes;let games=0;
 const progress=slot=>{const completed=playoffSeriesSlots().filter(s=>!s.bye&&s.complete&&(!roundOnly||s.round===round)).length;playoffSimulationProgress(slot,completed,total,completed+' / '+total+' series completed · '+games+' games completed this run');};
 try{render();while(state.champion===null&&gmCanAdvance()&&!simulationStopRequested){
  const slot=playoffSeriesSlots().find(s=>!s.complete&&(!roundOnly||s.round===round));
  if(!slot)break;
  progress(slot);await simulationYield();if(simulationStopRequested)break;
  if(!await simulatePlayoffGame(...slot.nextPair,false,token))break;
  games++;progress(playoffSeriesSlots().find(s=>!s.complete&&(!roundOnly||s.round===round)));await simulationYield();
 }}finally{playoffBatchToken=null;closePlayoffSimulationProgress();render();}
}
function simulatePlayoffRound(){return simulatePlayoffBatch(true)}
playoffs=function(){return simulatePlayoffBatch(false)};
viewPlayoffMatchup=function(a,b){const s=playoffSeriesSlots().find(s=>s.pair.includes(a)&&s.pair.includes(b));if(s)titleModal('Playoff matchup',playoffSeriesCard(s,false)+altitudePanel(altitudeEnvironment(s.pair[0],s.pair[1],'Playoffs'))+matchupComparison(a,b))};
postseasonSchedulePanel=function(){const league=scheduleSettings().audience==='league',c=playoffConfig(),slots=playoffSeriesSlots().filter(s=>league||s.pair.includes(scheduleTeamId()));return `<section class="panel schedule-postseason"><div class="panelhead"><h2>Playoff series</h2><span>${playoffSeriesFormat(c)}</span></div><div class="conference-round">${slots.map(s=>playoffSeriesCard(s)).join('')||'<p class="note">No playoff series for your team. Select Entire league to view all series.</p>'}</div><div class="schedule-actions">${simulateRoundButton()}<button onclick="${state.champion===null?'playoffs()':'newSeason()'}">${state.champion===null?'Simulate remaining playoffs':'Continue offseason'}</button></div></section>`};
